<?phpnamespace backend\models;use common\components\Helper;use common\models\User;use Yii;use yii\behaviors\TimestampBehavior;use yii\db\Exception;/** * This is the model class for table "{{%order}}". * * @property integer $id * @property integer $type * @property string $order_number * @property integer $user_id * @property string $consignee * @property string $phone * @property integer $address_id * @property string $address_detail * @property integer $invoice_id * @property integer $express * @property double $total_price * @property integer $pay_method * @property integer $pay_status * @property integer $status * @property string $content * @property integer $append * @property integer $updated * @property integer $paid_time * @property integer $delivery_time * @property integer $confirm_time * @property integer $is_delete * @property integer $category * @property string $freight * @property string $province * @property string $city * @property string $area * @property string $service_price * @property integer $integral * @property integer $is_delivery * @property string $other_money * @property string $invoice_company * @property string $invoice_number * @property string $invoice_address * @property string $invoice_phone * @property string $invoice_bank * @property string $invoice_username * @property string $weight * @property string $pay_price * @property integer $service_id * @property string $experience * @property string $express_number */class Order extends \yii\db\ActiveRecord{    /**     * @inheritdoc     */    public static function tableName()    {        return '{{%order}}';    }    public function behaviors()    {        return [            TimestampBehavior::className(),        ];    }    //订单类型    public static $type = [        1 => '普通',    ];    //订单状态    public static $status = [        '1' => '待付款',        '2' => '待发货',        '3' => '待收货',        '4' => '退款退货',        '5' => '已完成',        '-1' => '已取消',//        '-3'=>'已关闭'    ];    public static $pay_message=[        1=>'线上',        2=>'线下'    ];    /**     * @inheritdoc     */    public function rules()    {        return [            [['type', 'user_id', 'pay_method', 'pay_status', 'status', 'invoice_id', 'address_id', 'category','express','service_id'], 'integer'],            [['user_id'], 'required'],            [['order_number', 'phone'], 'string', 'max' => 50],            [['consignee', 'address_detail','express_number','province','city','area','express_name'], 'string', 'max' => 255],            [['content'], 'string'],            [['total_price', 'other_money', 'service_price','pay_price','freight','experience'], 'number']        ];    }    /**     * @inheritdoc     */    public function attributeLabels()    {        return [            'id' => 'ID',            'type' => '类型',            'order_number' => '订单号',            'user_id' => '用户',            'total_price' => '总价',            'pay_method' => '支付方式',            'pay_status' => '支付状态',            'status' => '状态',            'created_at' => '下单时间',            'updated_at' => '更新时间',            'content' => '备注',            'invoice_id' => '发票',            'express' => '配送方式',            'address_id' => '地址',            'consignee' => '收货人',            'phone' => '电话',            'address_detail' => '地址',            'category' => '是否预购',            'is_delivery' => '发货状态',            'freight' => '配送费',            'other_money' => '订单金额调整(-3表示优惠3元,3表示加价3元)',            'service_price' => '服务费',            'integral' => '订单积分',            'province' => '省',            'city' => '市',            'area' => '区',            'invoice_company' => '发票单位名称',            'invoice_number' => '发票识别号',            'invoice_address' => '发票注册地址',            'invoice_phone' => '发票电话',            'invoice_bank' => '发票银行',            'invoice_username' => '发票帐号',            'pay_price'=>'总价',            'service_id'=>'客服',            'experience'=>'经验',            'express_number'=>'快递单号',            'express_name'=>'快递名称',            'image'=>'付款图片'        ];    }    /**     * @param bool $insert     * @return bool     * 自动插入     */    public function beforeSave($insert)    {        if ($this->isNewRecord) {            $this->order_number = date('YmdHis', time()) . $this->user_id.mt_rand(1000,9999);        }        return parent::beforeSave($insert);    }    /**     * 关联用户     */    public function getUser()    {        return $this->hasOne(User::className(), ['id' => 'user_id']);    }    /**     * 关联地址     */    public function getAddress()    {        return $this->hasOne(Address::className(), ['id' => 'address_id']);    }    /**     * 关联订单详情     */    public function getDetail()    {        return $this->hasMany(OrderDetail::className(), ['order_id' => 'id'])->alias('detail');    }    /**     * 关联发票     */    public function getInvoice()    {        return $this->hasOne(OrderInvoice::className(), ['order_number' => 'order_number']);    }    /**     * 添加订单     *     * @param int $user_id 用户ID     * @param array $items 商品数组，支持两种格式：     *                    格式1: [goods_id => quantity] 无规格商品     *                    格式2: [sku_id => quantity] 有规格商品     *                    格式3: ['goods_123' => quantity, 'sku_456' => quantity] 混合格式     * @param int $address_id 地址ID     * @param int $pay_method 支付方式     * @param string $content 备注     * @param int $invoice_id 发票ID     * @param int $type 订单类型 1:普通订单     * @param int $category 订单分类     * @return int[] 成功返回订单ID，失败返回false     */    public static function addOrder($user_id, $items, $address_id, $pay_method, $content, $invoice_id=0, $type = 1, $category = 0)    {        $return=[            'error'=>1,            'order_id'=>0,            'message'=>''        ];        $transaction = Yii::$app->db->beginTransaction();        try {            // 1. 验证并获取地址信息            $address = Address::findOne($address_id);            if (!$address) {                throw new Exception('地址不存在');            }            // 2. 验证商品数据            if (empty($items) || !is_array($items)) {                throw new Exception('商品信息不能为空');            }            // 3. 创建订单主记录            $order = self::createOrder($user_id, $address, $invoice_id, $pay_method, $content, $type, $category);            // 4. 根据订单类型处理订单详情            if ($type == 1) {                // 普通订单                $totalPrice = self::processOrderItems($order, $items);                $order->total_price = $totalPrice;            } else {                // 特殊订单处理（可根据需要扩展）                throw new Exception('暂不支持该订单类型');            }            // 5. 计算积分//            $order->integral = self::calculateIntegral($order->total_price);            // 6. 最终保存            if (!$order->save()) {                $errors=$order->getFirstErrors();                throw new Exception('订单保存失败: ' . reset($errors));            }            $transaction->commit();            $return['error']=0;            $return['order_id']=$order->id;        } catch (\Exception $e) {            $transaction->rollBack();            Yii::error("下单失败: {$e->getMessage()}, UserID: {$user_id}, Items: " . json_encode($items), __METHOD__);            $return['message']=$e->getMessage();        }        return $return;    }    /**     * 处理订单商品项（支持有规格和无规格商品）     */    private static function processOrderItems(Order $order, array $items)    {        $totalPrice = 0;        $goodsItems = [];        $skuItems = [];        // 分离商品和SKU        foreach ($items as $key => $quantity) {            if ($quantity <= 0) {                continue;            }            if (strpos($key, 'sku_') === 0) {                // SKU格式: sku_123                $skuId = str_replace('sku_', '', $key);                $skuItems[$skuId] = $quantity;            } elseif (strpos($key, 'goods_') === 0) {                // 商品格式: goods_123                $goodsId = str_replace('goods_', '', $key);                $goodsItems[$goodsId] = $quantity;            } elseif (is_numeric($key) && $key > 0) {                // 纯数字：默认为SKU ID，兼容旧格式                $skuItems[$key] = $quantity;            }        }        // 处理有规格商品        if (!empty($skuItems)) {            $totalPrice += self::processSkuItems($order, $skuItems);        }        // 处理无规格商品        if (!empty($goodsItems)) {            $totalPrice += self::processGoodsItems($order, $goodsItems);        }        if ($totalPrice <= 0) {            throw new Exception('订单金额必须大于0');        }        return $totalPrice;    }    /**     * 处理有规格商品     */    private static function processSkuItems(Order $order, array $skuItems)    {        $totalPrice = 0;        // 批量查询SKU信息        $skuIds = array_keys($skuItems);        $skus = GoodsOption::find()            ->where(['id' => $skuIds])            ->with('goods') // 预加载商品信息            ->indexBy('id')            ->all();        foreach ($skuItems as $skuId => $quantity) {            if (!isset($skus[$skuId])) {                throw new Exception("SKU {$skuId} 不存在");            }            $sku = $skus[$skuId];            if (!$sku->goods) {                throw new Exception("SKU {$skuId} 没有所属产品");            }            // 检查库存            if ($sku->stock < $quantity) {                throw new Exception("商品【{$sku->goods->title}】规格【{$sku->title}】库存不足，剩余{$sku->stock}件");            }            $detail = new OrderDetail();            $detail->order_id = $order->id;            $detail->order_number = $order->order_number;            $detail->goods_id = $sku->goods_id;            $detail->sku_id = $skuId;            $detail->sku_value = $sku->title; // 保存规格名称            $detail->number = $quantity;            $detail->price = $sku->price;            $detail->title = $sku->goods->title;            $detail->image = $sku->goods->thumb ?: $sku->thumb;            if (!$detail->save()) {                throw new Exception('保存订单详情失败: ' . self::getFirstError($detail));            }            $totalPrice += $detail->price * $quantity;            // 扣减库存            $sku->stock -= $quantity;            if (!$sku->save()) {                throw new Exception('更新SKU库存失败');            }            // 同时更新商品总库存            $goods = $sku->goods;            $goods->stock -= $quantity;            $goods->save();        }        return $totalPrice;    }    /**     * 处理无规格商品     */    private static function processGoodsItems(Order $order, array $goodsItems): float|int    {        $totalPrice = 0;        // 批量查询商品信息        $goodsIds = array_keys($goodsItems);        $goodsList = Goods::find()            ->where(['id' => $goodsIds])            ->indexBy('id')            ->all();        foreach ($goodsItems as $goodsId => $quantity) {            if (!isset($goodsList[$goodsId])) {                throw new Exception("商品 {$goodsId} 不存在");            }            $goods = $goodsList[$goodsId];            // 检查库存            if ($goods->stock < $quantity) {                throw new Exception("商品【{$goods->title}】库存不足，剩余{$goods->stock}件");            }            // 检查商品是否有规格            if($goods->has_option==1){                throw new Exception("商品【{$goods->title}】需要选择规格");            }//            $hasSku = GoodsOption::find()->where(['goods_id' => $goodsId])->exists();//            if ($hasSku) {//                throw new Exception("商品【{$goods->title}】需要选择规格");//            }            $detail = new OrderDetail();            $detail->order_id = $order->id;            $detail->order_number = $order->order_number;            $detail->goods_id = $goodsId;            $detail->sku_id = 0; // 无规格商品SKU ID为0            $detail->number = $quantity;            $detail->price = $goods->price;            $detail->title = $goods->title;            $detail->image = $goods->thumb;            if (!$detail->save()) {                $errors=$detail->getFirstErrors();                throw new Exception('保存订单详情失败: ' .reset($errors));            }            $totalPrice += $detail->price * $quantity;            // 扣减库存            $goods->stock -= $quantity;            if (!$goods->save()) {                throw new Exception('更新商品库存失败');            }        }        return $totalPrice;    }    /**     * 创建订单主记录     */    private static function createOrder($userId, Address $address, $invoiceId, $payMethod, $content, $type, $category)    {        $order = new Order();        $order->user_id = $userId;        $order->address_id = $address->id;        $order->invoice_id = $invoiceId;        $order->consignee = $address->user;        $order->phone = $address->phone;        $order->category = $category;        $order->pay_method = $payMethod;        $order->content = $content ?: '';        $order->address_detail = $address->content;        $order->province = $address->province;        $order->city = $address->city;        $order->area = $address->area;        $order->type = $type;        $order->order_number = self::generateOrderNumber();        $order->status = 1; // 待付款状态        if (!$order->save()) {            $errors=$order->getFirstErrors();            throw new Exception('创建订单失败: ' .reset($errors) );        }        return $order;    }    /**     * 计算积分     */    private static function calculateIntegral($totalPrice): float    {        $conversionRate = Yii::$app->config->info('WEB_INTEGRAL_CONVERSION', 0) / 100;        return floor($totalPrice * $conversionRate); // 取整    }    /**     * 生成订单号     */    private static function generateOrderNumber()    {        return date('YmdHis') . substr(microtime(), 2, 4) . sprintf('%04d', mt_rand(0, 9999));    }    //取消订单    public static function cancel_order($id)    {        $re=[            'error'=>1,            'message'=>'取消失败',        ];        $order = Order::findOne($id);        if($order and $order->status == 1){            $order->status=-1;            if($order->save()){                $re['error']=0;            }        }        return $re;    }    /**     * 确认收货     */    public static function finishOrder($order_id){        $order=Order::findOne($order_id);        if($order->status==3){            $order->confirm_time = time();            $order->status = 5;            $user=ProvinceUser::findOne($order->user_id);            $user->integral+=$order->integral;            if(!$user->save()){                print_r($user->getFirstErrors());exit;            }            $order->save();            return true;        }else{            return false;        }    }    //关联配送方式    public function getFreightMessage(){        return $this->hasOne(FreightModel::className(),['id'=>'express']);    }    //关联客服    public function getServer(){        return $this->hasOne(Server::className(),['id'=>'service_id']);    }    public function getProvince(){        if($this->province_id){            $model=Provinces::findOne($this->province_id);            return $model->areaname;        }else{            return '';        }    }    public function getCity(){        if($this->city_id){            $model=Provinces::findOne($this->city_id);            return $model->areaname;        }else{            return '';        }    }    public function getArea(){        if($this->area_id){            $model=Provinces::findOne($this->area_id);            return $model->areaname;        }else{            return '';        }    }    public function getExpressName(){        if($this->express){            $freight=FreightModel::findOne($this->express);            if($freight){                return $freight->title;            }        }        return '';    }}